// Resolve P2 globals from the running DLL base rather than importing data
// symbols. ext_Log is a RIP-relative function reference, so this remains ASLR-safe.
static u8* p2_base(void) { return ((u8*)(void*)ext_Log) - 0x4320; }
// S5-P2 debug symbols / disassembly, all relative to p2_base().
// g_xrFrameBegun is atomically cleared by d_Swap immediately before its old
// late BeginFrame call.  Setting it after an EARLY successful BeginFrame makes
// d_Swap skip that late call and proceed directly to SubmitEye/EndFrame.
static volatile i32* p2_xr_frame_begun_ptr(void) { return (volatile i32*)(p2_base()+0x41500); }
