            if(g_h5755akWindow&&p_h5754dGetClientRect&&p_h5754dGetClientRect(g_h5755akWindow,&rc)){cw=rc.right-rc.left;ch=rc.bottom-rc.top;}
            g_h5755enBackingVerifiedW=cw;g_h5755enBackingVerifiedH=ch;
            __atomic_store_n(&g_h5755enBackingVerifyState,(cw==g_h5754eVrW&&ch==g_h5754eVrH)?1u:2u,__ATOMIC_RELEASE);
            if(cw==g_h5754eVrW&&ch==g_h5754eVrH)ext_Log(">>> S6-HANDS5755EO GAMEPLAY BACKING VERIFIED ONCE: current HWND client %dx%d == AK physical VR backing %dx%d | p2_full %dx%d is logical/stale metadata; real-eye crop may use physical backing | no viewport/IPD mutation",cw,ch,g_h5754eVrW,g_h5754eVrH,p2_full_w(),p2_full_h());
            else ext_Log(">>> S6-HANDS5755EO GAMEPLAY BACKING REJECT ONCE: current HWND client %dx%d != AK expected %dx%d | p2_full %dx%d retained as fail-open crop source; no out-of-bounds GL_BACK read",cw,ch,g_h5754eVrW,g_h5754eVrH,p2_full_w(),p2_full_h());
