static i32 h5753c_enable_gameplay_camera(void* state){
    h5753c_save_camera_authority_once();
    // Reconstruct once while HMD authority is definitely OFF.  This is the
    // missing manual-start timing property: gameplay begins from SOMA's authored
    // camera, not a logo/menu view that has already carried HMD transforms.
    __atomic_store_n(p2_camera_hook_ptr(),0u,__ATOMIC_RELEASE);
    __atomic_store_n(p2_head_mode_ptr(),6,__ATOMIC_RELEASE);
    __atomic_store_n(p2_origin_set_ptr(),0,__ATOMIC_RELEASE);
    __atomic_store_n(p2_origin_delay_ptr(),0,__ATOMIC_RELEASE);
    if(!h5753c_clean_authored_camera_view("gameplay entry"))return 0;
    void* gameplayCamera=__atomic_load_n(p2_camera_obj_slot(),__ATOMIC_ACQUIRE);
    if(!gameplayCamera||!h20_mem_readable(gameplayCamera,0x710u)){
        ext_Log(">>> S6-HANDS5755BP GAMEPLAY CAMERA CAPTURE FAILED CLOSED: exact authored gameplay boundary had unreadable camera %p; HMD authority stays gated",gameplayCamera);
        return 0;
    }
    /* H57.55FZ: a manual Continue can leave SOMA's active cViewport bound to
       the load/DUNBAT camera even though p2_camera_obj_slot() has already become
       Simon's authored gameplay camera. Rebind through SOMA's own cViewport API
       before publishing BP ownership or enabling HMD authority. If the semantic
       dispatch/readback is unavailable, fail closed and retry this boundary. */
    if(!h5755fz_rebind_gameplay_viewport(gameplayCamera)){
        ext_Log(">>> S6-HANDS5755FZ GAMEPLAY CAMERA ACTIVATION DEFERRED: authored viewport rebind has not been proven yet | gameplay camera %p | HMD authority stays OFF and frozen H57.51A main-view equality remains fail-closed",gameplayCamera);
        return 0;
    }
    __atomic_store_n(&g_h5755bpGameplayCamera,gameplayCamera,__ATOMIC_RELEASE);
    g_h5755bpGameplayCameraCaptures++;
    ext_Log(">>> S6-HANDS5755BP GAMEPLAY CAMERA CAPTURE #%u: exact authored gameplay boundary pins player cCamera3D %p; auxiliary cameras cannot replace P2 g_cameraObj or receive HMD pose",g_h5755bpGameplayCameraCaptures,gameplayCamera);
    g_h5753cGameplayReprimes++;
    ext_Log(">>> S6-HANDS5753H GAMEPLAY CAMERA REPRIME: player %p | viewT contaminated(%.3f %.3f %.3f) -> authored-clean(%.3f %.3f %.3f) before HMD authority; camera pos(%.3f %.3f %.3f)",state,
            (double)g_h5753cBeforeViewT[0],(double)g_h5753cBeforeViewT[1],(double)g_h5753cBeforeViewT[2],
            (double)g_h5753cAfterViewT[0],(double)g_h5753cAfterViewT[1],(double)g_h5753cAfterViewT[2],
            (double)g_h5753cLastCameraPos[0],(double)g_h5753cLastCameraPos[1],(double)g_h5753cLastCameraPos[2]);
    __atomic_store_n(p2_camera_hook_ptr(),1u,__ATOMIC_RELEASE);
    // H57.53 production always uses the proven normal translation mode.  The
    // saved value is retained only for diagnostics; a menu OFF gate must never
    // leak into gameplay.
    __atomic_store_n(p2_head_mode_ptr(),0,__ATOMIC_RELEASE);
    g_h5753cAuthorityEnabled=1;g_h5753cGameplayAuthorityOn++;
    h5735_request_recenter("gameplay-camera-activation");g_h5753bGameplayRecenter=1;
    ext_Log(">>> S6-HANDS5753H GAMEPLAY CAMERA AUTHORITY ON: player %p | clean authored rebuild passed | P2 cameraHook=1 headMode=0 | queued existing positional+yaw recenter; renderer/FOV/stereo math unchanged",state);
    ext_Log(">>> S6-HANDS5755V WINDOWED GAMEPLAY AUTHORITY ON: raw-world boundary released camera authority | next xrEndFrame will retire startup flat panel and resume the existing stereoscopic gameplay submission path | no projection/SubmitEye/viewport math changed");
    return 1;
}

static void h5753a_auto_bootstrap_after_lowlevel(void){
    if(g_h5753aBootstrapDone)return;g_h5753aBootstrapDone=1;
    PFN_H5753A_Install eng=(PFN_H5753A_Install)(void*)(p2_base()+H5753A_P2_INSTALL_ENGINE_RVA);
    PFN_H5753A_Install ren=(PFN_H5753A_Install)(void*)(p2_base()+H5753A_P2_INSTALL_RENDER_RVA);
    i32 eok=__atomic_load_n(p2_hook_on_ptr(),__ATOMIC_ACQUIRE)?1:(eng?eng():0);
    if(eok){__atomic_store_n(p2_hook_on_ptr(),1,__ATOMIC_RELEASE);g_h5753aEngineInstallOK++;}else g_h5753aEngineInstallFail++;
    i32 rok=__atomic_load_n(p2_sbs_on_ptr(),__ATOMIC_ACQUIRE)?1:(ren?ren():0);
    if(rok){__atomic_store_n(p2_sbs_on_ptr(),1,__ATOMIC_RELEASE);g_h5753aRenderInstallOK++;}else g_h5753aRenderInstallFail++;
    // Camera hook is installed by the frozen P2 engine installer, but do not let
    // its HMD authority touch startup/logo/menu cameras.  Projection/stereo stay on.
    h5753c_gate_menu_camera("startup",0);
    h5753b_seed_p2_camera_contract();
    h5753a_try_auto_xr_init("LowLevelInit");
    // Install the already-frozen early BeginFrame bridge even if the first XR
    // init attempt failed, so first render provides a bounded retry point.
    h5750a_try_install_early_xr_frame_hook();
    ext_Log(">>> S6-HANDS5753H AUTO BOOTSTRAP: F2 engine %s | F10 stereo %s | F7 auto attempt %u success %u | P2 camera recognition pre-seeded | main-menu VR startup path armed",eok?"ON":"FAILED",rok?"ON":"FAILED",g_h5753aAutoXrAttempts,g_h5753aAutoXrSuccess);
}

