static void h30_native_use_motion(i32 hand,const float* handVel,float dt){
    if(s26bp_exact_tear()){s26bp_slider_tear(hand);return;}
    if(!g_h30NativeMouseDown||g_h30NativeUseHand!=hand||!handVel||dt<=0.0005f)return;
    if(hand>=0&&hand<2){g_h38NativeUseAge[hand]+=dt;if(g_h38NativeUseAge[hand]>2.0f)g_h38NativeUseAge[hand]=2.0f;}
    // H57.55CH: exact authored Grab is a semantic shell only. The physical
    // tracked-hand anchor already owns motion, so do not let the historical
    // generic native-use analog path synthesize Look/Move into Grab as a second
    // motion/camera owner after state commitment.
    if(g_h5755chGrabStateActive&&g_h5755chGrabPrimaryHand==hand)return;
    // H57.55bs: once the exact authored Slide state consumes the handshake, hand
    // motion is fed through SOMA's own OnAnalogInput/Slide controller whenever
    // the joint pin has a usable CameraRight/CameraUp projection. H39 is no
    // longer the default force owner.
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h39SliderValid[hand]){
        h5755bs_drive_authored_slider(hand,handVel,dt);return;
    }
    /* H57.55GB: exact Lever is also a RotateBase state. GA hardware showed the
       old generic tangent point-impulse stretching the hinge pivot while the
       translation brace saturated. Feed controller motion into authored
       Lever/RotateBase analog instead. */
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&
       h5755fn_exact_lever_names(g_h5729LastModuleName,g_h5729LastClassName)){
        h5755gb_drive_authored_lever(hand,handVel,dt);return;
    }
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h481MechanismKind[hand]==H481_MECH_HINGE&&g_h481HingeValid[hand]){
        // CD: exact SwingDoor identity (observed asynchronously below) owns the
        // handoff. Until then, fail closed rather than allowing the superseded
        // H48.1 tangent AddImpulse motor to touch the hinge.
        if(g_h5755ceNativeSwingDoorActive[hand]){h45_track_detached_yaw(hand);h5755ce_drive_authored_swingdoor(hand,handVel,dt);}
        else if(g_h5755ceSwingDoorPendingNative[hand]++<2u)ext_Log(">>> S6-HANDS5755CD NATIVE SWINGDOOR PENDING %s: semantic hinge consumed Look; waiting for exact PlayerState_Interact_SwingDoor identity | legacy H48.1 point-impulse motor DELETED",hand==0?"L":"R");
        return;
    }
    // H57.55CD native articulated-door handoff. Graph resolution is retained only
    // to identify the authored panel hinge/anchor; H48.3 no longer owns motion in
    // an exact SwingDoor hold. Mouse detach/lifetime is committed by the exact
    // state observer, and native RotateBase torque owns the panel until release.
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h482ArticulatedValid[hand]){
        // Jointed graph doors normally bypass this function, but if one reaches
        // it, never resurrect the retired door motor. Exact SwingDoor state observation arms CD.
        if(g_h5755ceNativeSwingDoorActive[hand]){h45_track_detached_yaw(hand);h5755ce_drive_authored_swingdoor(hand,handVel,dt);}
        return;
    }
    // H48.2: if a fresh grip-edge OnInteract entered a scripted continuous state
    // but no safe native Slider/Hinge substitute exists, retain that authored
    // state instead of fail-closing it. The held-grip acquisition lock still
    // prevents approaching a curtain/faucet later in the same squeeze cycle.
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h481MechanismKind[hand]==H481_MECH_NONE){
        h482_authored_drag_begin(hand);h482_dispatch_authored_drag(hand,handVel,dt);return;
    }
    // Before state commitment, keep H48.1's zero-valued handshake. This cannot
    // move either the object or the camera; it only proves whether the state owns
    // Look. If it becomes consumed, the branch below starts authored drag now.
    h34_dispatch_native_analog(hand,handVel,dt);
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h39SliderValid[hand]){h5755bs_drive_authored_slider(hand,handVel,dt);return;}
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&
       h5755fn_exact_lever_names(g_h5729LastModuleName,g_h5729LastClassName)){
        h5755gb_drive_authored_lever(hand,handVel,dt);return;
    }
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h481MechanismKind[hand]==H481_MECH_HINGE&&g_h481HingeValid[hand]){
        if(g_h5755ceNativeSwingDoorActive[hand]){h45_track_detached_yaw(hand);h5755ce_drive_authored_swingdoor(hand,handVel,dt);}
        else if(g_h5755ceSwingDoorPendingNative[hand]++<2u)ext_Log(">>> S6-HANDS5755CD NATIVE SWINGDOOR PENDING %s: semantic hinge handshake consumed; waiting for exact SwingDoor identity | H48.1 point-impulse motor DELETED",hand==0?"L":"R");
        return;
    }
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h482ArticulatedValid[hand]){if(g_h5755ceNativeSwingDoorActive[hand]){h45_track_detached_yaw(hand);h5755ce_drive_authored_swingdoor(hand,handVel,dt);}return;}
    if(hand>=0&&hand<2&&g_h38ThisUseConsumed[hand]&&g_h481MechanismKind[hand]==H481_MECH_NONE){h482_authored_drag_begin(hand);h482_dispatch_authored_drag(hand,handVel,dt);}
}

#define H9_CAL_MAGIC 0x31433948u /* H9C1 */
typedef struct { u32 magic,version; float rot[6],spread,reach,drop,curlGain; } H9Calib;
static H9Calib g_savedCalib;
static i32 g_haveSavedCalib;
static char g_calibPath[512];
static float g_curlGain=0.65f;

static void zero_bytes(void* p, u32 n) { u8* d=(u8*)p; for (u32 i=0;i<n;++i) d[i]=0; }
static void copyz(char* d, u32 cap, const char* s) {
    if (!cap) return; u32 i=0; while (i+1<cap && s[i]) { d[i]=s[i]; ++i; } d[i]=0;
}
static float h9_abs(float v){ return v<0.0f?-v:v; }
static i32 h9_good(float v,float lim){ return v==v && h9_abs(v)<lim; }
static i32 make_sibling_path(char* out,u32 cap,const char* leaf){
    if(!out||cap<8) return 0;
    u32 n=ext_GetModuleFileNameA((void*)p2_base(),out,cap-1); if(!n||n>=cap-1) return 0;
    out[n]=0; i32 slash=-1; for(u32 i=0;i<n;++i) if(out[i]=='\\'||out[i]=='/') slash=(i32)i;
    u32 pos=(slash>=0)?(u32)slash+1:0; u32 j=0;
    while(leaf[j] && pos+1<cap) out[pos++]=leaf[j++]; out[pos]=0; return leaf[j]==0;
}
static void capture_calib(H9Calib* c){
    c->magic=H9_CAL_MAGIC; c->version=1; float* r=p2_hand_rot();
    for(i32 i=0;i<6;++i)c->rot[i]=r[i]; c->spread=*p2_hand_spread(); c->reach=*p2_hand_reach(); c->drop=*p2_hand_drop(); c->curlGain=g_curlGain;
}
static i32 calib_valid(const H9Calib* c){
    if(!c||c->magic!=H9_CAL_MAGIC||c->version!=1) return 0;
    for(i32 i=0;i<6;++i) if(!h9_good(c->rot[i],20.0f)) return 0;
    return h9_good(c->spread,2.0f)&&h9_good(c->reach,3.0f)&&h9_good(c->drop,3.0f)&&c->curlGain>=0.20f&&c->curlGain<=1.20f&&c->curlGain==c->curlGain;
}
static void apply_calib(const H9Calib* c){
    float* r=p2_hand_rot(); for(i32 i=0;i<6;++i) r[i]=c->rot[i]; *p2_hand_spread()=c->spread; *p2_hand_reach()=c->reach; *p2_hand_drop()=c->drop; g_curlGain=c->curlGain;
}
static i32 calib_changed(const H9Calib* a,const H9Calib* b){
    for(i32 i=0;i<6;++i) if(h9_abs(a->rot[i]-b->rot[i])>0.00001f) return 1;
    if(h9_abs(a->spread-b->spread)>0.00001f||h9_abs(a->reach-b->reach)>0.00001f||h9_abs(a->drop-b->drop)>0.00001f||h9_abs(a->curlGain-b->curlGain)>0.00001f) return 1; return 0;
}
static void save_calibration(i32 force){
    H9Calib now; capture_calib(&now); if(!force&&g_haveSavedCalib&&!calib_changed(&now,&g_savedCalib)) return;
    if(!g_calibPath[0]&&!make_sibling_path(g_calibPath,sizeof(g_calibPath),"hpl3vr_hand_calibration.bin")) return;
    void* f=ext_fopen(g_calibPath,"wb"); if(!f){ ext_Log(">>> S6-HANDS34 CALIBRATION: could not write %s",g_calibPath); return; }
    u64 n=ext_fwrite(&now,1,sizeof(now),f); ext_fclose(f); if(n!=sizeof(now)) return;
    g_savedCalib=now; g_haveSavedCalib=1;
    ext_Log(">>> S6-HANDS34 CALIBRATION SAVED: L(%.4f %.4f %.4f) R(%.4f %.4f %.4f) | reach %.3f spread %.3f height %.3f (legacy curl field preserved only for H9 file compatibility)",
      now.rot[0],now.rot[1],now.rot[2],now.rot[3],now.rot[4],now.rot[5],now.reach,now.spread,now.drop);
}
static void load_calibration(void){
    if(!make_sibling_path(g_calibPath,sizeof(g_calibPath),"hpl3vr_hand_calibration.bin")) return;
    void* f=ext_fopen(g_calibPath,"rb"); H9Calib c; i32 loaded=0;
    if(f){ u64 n=ext_fread(&c,1,sizeof(c),f); ext_fclose(f); if(n==sizeof(c)&&calib_valid(&c)){ apply_calib(&c); g_savedCalib=c; g_haveSavedCalib=1; loaded=1; } }
    if(loaded) ext_Log(">>> S6-HANDS34 CALIBRATION LOADED: L(%.4f %.4f %.4f) R(%.4f %.4f %.4f) | reach %.3f spread %.3f height %.3f (legacy curl field ignored by H10)",
      c.rot[0],c.rot[1],c.rot[2],c.rot[3],c.rot[4],c.rot[5],c.reach,c.spread,c.drop);
    else { capture_calib(&g_savedCalib); g_haveSavedCalib=1; save_calibration(1); ext_Log(">>> S6-HANDS34 CALIBRATION: created persistent defaults at %s",g_calibPath); }
}
