static i32 visual_pose_valid(i32 hand) {
    if (hand < 0 || hand > 1 || !g_poseReady) return 0;
    if(g_lastActive[hand] && ((g_lastFlags[hand] & 3ULL) == 3ULL)) return 1;
    // H517: once a collision-safe free-hand pose exists, a dual grip+aim
    // outage must NEVER make the mesh disappear. Retain that pose until live
    // tracking returns; H516's 300-frame cutoff was a render/lifecycle policy,
    // not a physical requirement.
    return g_h510HadValidPose[hand] && g_h513SafeValid[hand] && g_h510PoseInvalidFrames[hand]>0u;
}

static i32 h5748o_yaw_zero_active(void){
    return __atomic_load_n(&g_h5745YawZeroSet,__ATOMIC_ACQUIRE);
}
static void h5748o_apply_yaw_zero_xz(float* x,float* z){
    if(!x||!z||!h5748o_yaw_zero_active())return;
    float c=g_h5745YawInvC,sy=g_h5745YawInvS;
    // Quaternion (0,sy,0,c) -> exact full-angle Y rotation. This is the
    // same inverse captured yaw that h5745_current_head_pose_detour applies
    // to the HMD orientation; applying it here keeps controller tracking in
    // the same horizontal reference frame after Y-center.
    float rc=c*c-sy*sy,rs=2.0f*c*sy;
    float ox=*x,oz=*z;
    *x=rc*ox+rs*oz;
    *z=-rs*ox+rc*oz;
    g_h5748oFrameSyncVecCalls++;
    u32 epoch=g_h5745YawCaptures;
    if(epoch&&g_h5748oFrameSyncEpoch!=epoch){
        g_h5748oFrameSyncEpoch=epoch;
        ext_Log(">>> S6-HANDS5748O RECENTER FRAME SYNC ACTIVE: yaw capture epoch %u | controller position/orientation/velocity now use the SAME inverse yaw as CurrentHeadPose; hand reach/spread/height calibration unchanged",epoch);
    }
}
static void h5748o_tracking_horizontal_to_game(float dx,float dz,float* gx,float* gz){
    h5748o_apply_yaw_zero_xz(&dx,&dz);
    float yaw=p2_player_yaw(),cy=ext_Cosf(yaw),sy=ext_Sinf(yaw);
    *gx=cy*dx+sy*dz;
    *gz=-sy*dx+cy*dz;
}
static void tracking_vector_to_game_unscaled(float dx,float dy,float dz,float* wx,float* wy,float* wz){
    float tx=dx,tz=dz;h5748o_apply_yaw_zero_xz(&tx,&tz);
    float yaw=p2_player_yaw(),cy=ext_Cosf(yaw),sy=ext_Sinf(yaw);
    float gx=cy*tx+sy*tz,gz=-sy*tx+cy*tz,gy=dy; i32 hm=p2_head_mode();
    float x=gx,y=gy,z=gz;
    switch(hm){case 1:x=gx;z=-gz;break;case 2:x=-gx;z=gz;break;case 3:x=gz;z=gx;break;case 4:x=-gx;y=-gy;z=-gz;break;case 5:x=tx;y=dy;z=tz;break;default:break;}
    *wx=x;*wy=y;*wz=z;
}
static void tracking_delta_to_game(float dx, float dy, float dz, float* wx, float* wy, float* wz) {
    // ET: map physical tracking metres into authored SOMA world units without
    // resizing Simon's hand meshes. This preserves hand<->prop authored scale.
    float metric=h5755ea_world_units_per_meter();dx*=metric;dy*=metric;dz*=metric;
    float tx=dx,tz=dz;
    h5748o_apply_yaw_zero_xz(&tx,&tz);
    float yaw=p2_player_yaw(),cy=ext_Cosf(yaw),sy=ext_Sinf(yaw);
    float gx=cy*tx+sy*tz,gz=-sy*tx+cy*tz;
    // Keep the same recentered raw pair for legacy head-mode-5 diagnostics.
    float gy=dy;
    i32 hm=p2_head_mode();
    float x=gx, y=gy, z=gz;
    switch (hm) {
      case 1: x=gx;  z=-gz; break;
      case 2: x=-gx; z=gz;  break;
      case 3: x=gz;  z=gx;  break;
      case 4: x=-gx; y=-gy; z=-gz; break;
      case 5: x=tx; y=dy; z=tz; break;
      default: break;
    }
    *wx=x; *wy=y; *wz=z;
}

