// H22: decode the MSVC x64 RTTI record that lives immediately before a
// vftable. This is passive/read-only: it never calls the object. On x64 MSVC,
// CompleteObjectLocator signature 1 stores image-relative RVAs for the type
// descriptor and a self RVA. We still use VirtualQuery's AllocationBase as the
// authoritative module base and guard every dereference.
typedef struct {
    u32 signature;
    i32 offset;
    i32 cdOffset;
    i32 typeDescriptorRva;
    i32 classDescriptorRva;
    i32 selfRva;
} H22COL64;
_Static_assert(sizeof(H22COL64)==24, "MSVC x64 CompleteObjectLocator ABI");

static i32 h22_rtti_name(const void* obj,char* out,u32 cap){
    if(!out||cap<8)return 0;out[0]=0;
    if(!obj||!h20_mem_readable(obj,8))return 0;
    void* vt=*(void* const*)obj;
    if(!vt||!h20_mem_readable((const u8*)vt-8,8))return 0;
    void* colp=*((void* const*)vt-1);
    if(!colp||!h20_mem_readable(colp,sizeof(H22COL64)))return 0;
    H22COL64 col=*(const H22COL64*)colp;
    if(col.signature!=1 || col.typeDescriptorRva<=0)return 0;
    H20MBI vm;
    if(!h20_mem_query(vt,&vm)||!vm.AllocationBase)return 0;
    const u8* base=(const u8*)vm.AllocationBase;
    const u8* td=base+(u32)col.typeDescriptorRva;
    // MSVC TypeDescriptor = two pointers followed by a NUL-terminated decorated name.
    if(!h20_mem_readable(td,17))return 0;
    return h21_copy_ascii(td+16,out,cap);
}

