    if(h5716_ci_contains(z,"body_divingsuit_lamp")||h5716_ci_contains(z,"legs_simon_divingsuit")||h5716_ci_contains(z,"simon_legs_divingsuit")){if(outKind)*outKind=H5748N_AUTH_BODY;return H5748_FAMILY_DIVING;}
