// Distances are physical metres. Move the existing monitor along its own
// forward direction; no recenter, raster resize, or UI-coordinate change.
static void s26be_set_distance(i32 subtitle,u32 index){
    if(index>65u)return;
    float value=(75.0f+5.0f*(float)index)*0.01f;
    if(subtitle){g_s26beSubtitleDistance=value;return;}
    float delta=value-g_s26bePanelDistance;
    if(delta==0.0f)return;
    g_s26bePanelDistance=value;
    if(g_h5754dPanelAnchorValid){
        XrVector3f f=h5754d_q_rotate_vec(g_h5754dPanelPose.orientation,(XrVector3f){0.0f,0.0f,-1.0f});
        g_h5754dPanelPose.position.x+=f.x*delta;
        g_h5754dPanelPose.position.y+=f.y*delta;
        g_h5754dPanelPose.position.z+=f.z*delta;
    }
}
