                            u64 orv=((PFN_H25_OnInteract)on)(entity,0,bodyWrapper,area->contact,&empty);g_h25LastOnRet[hand]=orv;g_h25OnCalls[hand]++;h25_copyz(g_h25LastOwnerRtti[hand],sizeof(g_h25LastOwnerRtti[hand]),rt);
