    if(g_h576btRenderProbeLogs[hand]>=40u||g_s26RockerDiagnosticSamples[hand]>=2400u)return;
    if(g_h576btRenderProbeFrame[hand]==g_frameCounter)return;
    g_h576btRenderProbeFrame[hand]=g_frameCounter;
