    if(!rocker){g_h576btRenderProbeValid[hand]=0;g_h576btRockerBodyPrevValid[hand]=0;g_h576btRockerBodyPrev[hand]=0;return;}
    if(!g_h531TrackedTargetValid[hand])return;
