    g_h576btPrevRawTip[hand][0]=rawTip[0];g_h576btPrevRawTip[hand][1]=rawTip[1];g_h576btPrevRawTip[hand][2]=rawTip[2];
    g_h576btPrevRenderRoot[hand][0]=renderM[12];g_h576btPrevRenderRoot[hand][1]=renderM[13];g_h576btPrevRenderRoot[hand][2]=renderM[14];g_h576btRenderProbeValid[hand]=1;
