// H47 deliberately does not make camera/character collision bodies transparent
// to Newton. They are ignored only as *interaction ownership* clues. This keeps
// locomotion/head collision physics untouched while allowing a nearby authored
// Slider prop to be considered when a player-self body is the nearest contact.
static i32 h47_self_occluder_kind(const void* body){
    if(!body||!p_h14GetUserData)return 0;void* w=p_h14GetUserData(body);if(!w)return 0;char rt[96];rt[0]=0;
    if(h20_mem_readable((u8*)w+0x2c8,8)){void* q=*(void**)((u8*)w+0x2c0);if(q&&h22_rtti_name(q,rt,sizeof(rt))&&h25_str_contains(rt,"cLuxCameraEntity"))return 1;}
    rt[0]=0;if(h20_mem_readable((u8*)w+0x168,8)){void* q=*(void**)((u8*)w+0x160);if(q&&h22_rtti_name(q,rt,sizeof(rt))&&h25_str_contains(rt,"cCharacterBodyNewton"))return 2;}
    return 0;
}

#define H47_MAX_OWNERS 16
