    H25PendingInteract* p=&g_h25Pending[hand];zero_bytes(p,sizeof(*p));p->newtonBody=c->body;p->bodyWrapper=wrapper;p->entity=entity;p->canFn=can;p->onFn=on;
    p->contact[0]=c->contact[0];p->contact[1]=c->contact[1];p->contact[2]=c->contact[2];p->meshGap=probeGap;p->broadGap=c->gap;p->ownerOffset=ownerOff;p->physicsStep=g_h14PhysicsSteps;p->jointed=0;
    g_h25PendingValid[hand]=1;g_h25Queued[hand]++;g_h47Queued[hand]++;h25_copyz(g_h25LastOwnerRtti[hand],sizeof(g_h25LastOwnerRtti[hand]),rt);
    g_h47LastOwner[hand]=entity;g_h47LastWrapper[hand]=wrapper;g_h47LastBody[hand]=c->body;g_h47LastGap[hand]=c->gap;g_h47LastShell[hand]=c->shell;g_h47LastAlong[hand]=c->along;g_h47LastScore[hand]=c->score;
