        float pin[3];void* joint=0;if(!h42_slider_pin(owner,&joint,pin))continue;
        i32 k=-1;for(i32 j=0;j<n;++j)if(o[j].owner==owner){k=j;break;}if(k<0){if(n>=H47_MAX_OWNERS)continue;k=n++;o[k].owner=owner;o[k].score=999.0f;o[k].gap=o[k].dist=o[k].shell=o[k].along=999.0f;o[k].point=-1;}
        float bestGap=999.0f,bestDist=999.0f,cp[3]={0,0,0};i32 bestPoint=-1;
        for(i32 pidx=0;pidx<6;++pidx){float d=999.0f,cpt[3];if(!s26br_mechanism_point(body,probe[pidx],&d,cpt))continue;float gap=d-prad[pidx];if(gap<bestGap){bestGap=gap;bestDist=d;bestPoint=pidx;cp[0]=cpt[0];cp[1]=cpt[1];cp[2]=cpt[2];}}
        if(bestPoint<0||bestGap>H47_DIRECT_GAP_MAX_M)continue;
        float shell=999.0f,along=999.0f;if(bestDist==0.0f&&s26br_noncolliding_mechanism(body)){shell=0.0f;along=0.0f;}else if(!h47_axis_shell_hits_body(body,probe[bestPoint],pin,&shell,&along)||shell>H47_DIRECT_SHELL_MAX_M)continue;
