    if(best<0){g_h47NoMatch[hand]++;g_h5752cNoProbeMatch[hand]++;if(n>=2){g_h47Ambiguous[hand]++;g_h5752cFixedProbeAmbiguous[hand]++;g_h5752cSliderEdgeState[hand]=-1;ext_Log(">>> S6-HANDS5752C SLIDER CLUSTER FAIL-CLOSED %s: %d neighboring Slider owners cached but fixed Grip probe reaches none; suppressing legacy projected-owner guess for this Grip edge",hand==0?"L":"R",n);return -1;}return 0;}
    if(second>=0&&ss-bs<H52C_OWNER_TIE_M){g_h47Ambiguous[hand]++;g_h5752cFixedProbeAmbiguous[hand]++;g_h5752cSliderEdgeState[hand]=-1;ext_Log(">>> S6-HANDS5752C GRIP-ONLY SLIDER AMBIGUOUS %s: fixed probe best owner %p score %.4f vs second %p %.4f (< %.3f); Trigger is irrelevant and no neighboring drawer is guessed",hand==0?"L":"R",o[best].owner,bs,o[second].owner,ss,H52C_OWNER_TIE_M);return -1;}
