static void __attribute__((ms_abi)) h48_player_analog_yaw_only(void* playerIface,i32 analogId,const float* amount){
    if(!o_h48PlayerAnalog)return;
    // Ordinary player Look remains yaw-only. The one exception is an H48.2
    // synthetic packet after a fresh grip-edge scripted state has ALREADY proved
    // it consumes Look; that packet may carry both authored drag axes to the
    // interaction state. If it ever propagates, h37a_global_player_analog_guard
    // drops it before normal camera/body look.
    if(analogId==H34_ANALOG_LOOK&&amount){
        i32 h=g_h37aSyntheticAnalogHand;
        if(g_h37aSyntheticAnalogDepth&&h>=0&&h<2&&(s26bp_exact_tear()||g_h482AuthoredDragActive[h]||g_h5755bsAuthoredSlideActive[h]||g_h5755ceNativeSwingDoorActive[h]||h5755fn_exact_lever_names(g_h5729LastModuleName,g_h5729LastClassName)||h576az_exact_wheel_names(g_h5729LastModuleName,g_h5729LastClassName))){o_h48PlayerAnalog(playerIface,analogId,amount);return;}
        float a[4]={amount[0],0.0f,amount[2],0.0f};
        if(amount[1]>0.00001f||amount[1]<-0.00001f)g_h48AnalogPitchClamps++;
        o_h48PlayerAnalog(playerIface,analogId,a);return;
    }
    o_h48PlayerAnalog(playerIface,analogId,amount);
}

static void __attribute__((ms_abi)) h37a_global_player_analog_guard(void* playerIface,i32 analogId,const float* amount){
    if(g_h37aSyntheticAnalogDepth&&analogId==H34_ANALOG_LOOK){
        i32 h=g_h37aSyntheticAnalogHand;if(h>=0&&h<2)g_h37aGlobalLookSuppressed[h]++;
        g_h37aSyntheticFellThrough=1;
        // Do not let a synthetic hand-drag become ordinary camera/body look.
        return;
    }
    if(o_h37aGlobalPlayerAnalog)o_h37aGlobalPlayerAnalog(playerIface,analogId,amount);
}

static void* h34_player_input_interface(void){
    u8* soma=(u8*)ext_GetModuleHandleA(0);if(!soma)return 0;if(!h20_mem_readable(soma+H34_LUX_GLOBAL_RVA,8))return 0;
    void* owner=*(void**)(soma+H34_LUX_GLOBAL_RVA);if(!owner||!h20_mem_readable((u8*)owner+0x140,8))return 0;
    void* player=*(void**)((u8*)owner+0x140);if(!player||!h20_mem_readable(player,0x118))return 0;
    // Reverse engineering established that FUN_14015A690 is slot 29 of the
    // interface vtable installed at cLuxPlayer+0x110. H34 incorrectly demanded
    // that BOTH the complete-object vptr and the +0x110 subobject vptr equal the
    // same vtable, which is impossible for this multiple-vtable object and made
    // every native analog call reject. Validate the actual receiver only.
    void* pi=(u8*)player+0x110;void* expect=soma+H34_PLAYER_VTABLE_RVA;
    if(*(void**)pi!=expect)return 0;
    if(!g_h36AnalogIfaceLogged){g_h36AnalogIfaceLogged=1;ext_Log(">>> S6-HANDS36 NATIVE ANALOG INTERFACE VERIFIED: cLuxPlayer %p +0x110 %p vtable %p | dispatch Soma.exe+0x15A690",player,pi,*(void**)pi);}
    return pi;
}

