// Apply after NewtonUpdate returns. Do not change a held object's controller frame.
static void s26bb_apply_world_scale(void){
    u32 percent=__atomic_load_n(&g_s26bbWorldScalePercent,__ATOMIC_ACQUIRE);
    if(percent<50u||percent>200u||!p2_xr_on()||!p2_xr_running())return;
    if(g_h14GripBody[0]||g_h14GripBody[1]||g_h30NativeMouseDown||g_s26ManualHeal||
       g_h5748SwitchStage||g_h576bfMapTransitionActive||g_s26vDeathActive||g_s26vDeathLoading)return;
    float metric=100.0f/(float)percent;
    __atomic_store_n(&g_s26bbWorldScalePercent,0u,__ATOMIC_RELEASE);
    if(h9_abs(metric-g_h5755euWorldScale)<0.00001f)return;
    s26bb_retire_scaled_geometry(0);s26bb_retire_scaled_geometry(1);
    g_h5755euWorldScale=metric;
    *p2_eye_offset_scale_ptr()=metric;
    g_h5755ebSubtitleAnchorValid=0;g_h5755fmSubtitleLatePoseValid=0;
    if(g_h5753cAuthorityEnabled)h5735_request_recenter("world-scale-change");
    ext_Log(">>> S26BB WORLD SCALE: %u percent -> %.4f world-units/physical-m; hand visual and collision geometry compensated together; applied after physics with neither hand holding an item",percent,metric);
}

